(() => {
  const STORAGE_KEY = "inimark-site-theme";
  const root = document.documentElement;
  const toggle = document.getElementById("site-theme-toggle");
  const lightTheme = root.getAttribute("data-theme-light") || "light";
  const darkTheme = root.getAttribute("data-theme-dark") || "ocean";

  const currentMode = () =>
    root.dataset.appearance === "dark" || root.getAttribute("data-theme") === darkTheme
      ? "dark"
      : "light";

  const applyAppearance = (mode) => {
    const next = mode === "dark" ? "dark" : "light";
    root.dataset.appearance = next;
    root.setAttribute("data-theme", next === "dark" ? darkTheme : lightTheme);
    localStorage.setItem(STORAGE_KEY, next);
  };

  // Re-apply after DOM ready in case boot script and default attrs raced.
  {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved === "dark" || saved === darkTheme) applyAppearance("dark");
    else if (saved === "light" || saved === lightTheme) applyAppearance("light");
    else if (saved && /dark/i.test(saved)) applyAppearance("dark");
    else applyAppearance(currentMode());
  }

  const LIGHT_FALLBACKS = {
    surface: "#ffffff",
    secondary: "#f6f8fa",
    tertiary: "#eaeef2",
    contentBg: "#ffffff",
    code: "#f6f8fa",
    fg: "#1f2328",
    muted: "#656d76",
    border: "#d0d7de",
    accent: "#0969da",
    accentHover: "#0550ae",
    danger: "#cf222e",
    blockquoteBg: "#f6f8fa",
    blockquoteBorder: "#d0d7de",
  };
  const DARK_FALLBACKS = {
    surface: "#1b1d24",
    secondary: "#111217",
    tertiary: "#25272b",
    contentBg: "#1b1d24",
    code: "#1f2129",
    fg: "#ece7dd",
    muted: "#aeb6c2",
    border: "#4a4d52",
    accent: "#8ab4e7",
    accentHover: "#b994f4",
    danger: "#ff8f86",
    blockquoteBg: "#2d2a22",
    blockquoteBorder: "#8a7440",
  };

  const clampByte = (n) => Math.min(255, Math.max(0, Math.round(n)));
  const toHex = ({ r, g, b }) =>
    "#" +
    [r, g, b]
      .map((n) => clampByte(n).toString(16).padStart(2, "0"))
      .join("");

  const parseCssColor = (value) => {
    const trimmed = String(value || "").trim();
    if (!trimmed || trimmed === "transparent") return null;
    if (/^#[0-9a-fA-F]{3,8}$/.test(trimmed)) {
      let hex = trimmed.slice(1);
      if (hex.length === 3 || hex.length === 4) {
        hex = hex
          .split("")
          .map((c) => c + c)
          .join("");
      }
      return {
        r: parseInt(hex.slice(0, 2), 16),
        g: parseInt(hex.slice(2, 4), 16),
        b: parseInt(hex.slice(4, 6), 16),
        a: hex.length >= 8 ? parseInt(hex.slice(6, 8), 16) / 255 : 1,
      };
    }
    const rgb = trimmed.match(
      /^rgba?\(\s*([\d.]+)\s*[,\s]\s*([\d.]+)\s*[,\s]\s*([\d.]+)(?:\s*[,/]\s*([\d.]+%?))?\s*\)$/i,
    );
    if (rgb) {
      let a = 1;
      if (rgb[4] != null) {
        a = rgb[4].endsWith("%") ? parseFloat(rgb[4]) / 100 : Number(rgb[4]);
      }
      return {
        r: Number(rgb[1]),
        g: Number(rgb[2]),
        b: Number(rgb[3]),
        a: Math.min(1, Math.max(0, a)),
      };
    }
    try {
      const canvas = document.createElement("canvas");
      canvas.width = canvas.height = 1;
      const ctx = canvas.getContext("2d", { willReadFrequently: true });
      if (ctx) {
        ctx.clearRect(0, 0, 1, 1);
        ctx.fillStyle = "#000";
        ctx.fillStyle = trimmed;
        ctx.fillRect(0, 0, 1, 1);
        const [r, g, b, a] = ctx.getImageData(0, 0, 1, 1).data;
        if (r + g + b + a > 0 || /^black$/i.test(trimmed) || trimmed === "#000" || trimmed === "#000000") {
          return { r, g, b, a: a / 255 };
        }
      }
    } catch (_) {}
    return null;
  };

  const toMermaidColor = (value, fallback, backdrop = "#ffffff") => {
    const parsed = parseCssColor(value) || parseCssColor(fallback);
    const fb = parseCssColor(fallback) || { r: 128, g: 128, b: 128, a: 1 };
    const color = parsed || fb;
    if (color.a >= 0.999) return toHex(color);
    const base = parseCssColor(backdrop) || { r: 255, g: 255, b: 255, a: 1 };
    const a = color.a;
    return toHex({
      r: color.r * a + base.r * (1 - a),
      g: color.g * a + base.g * (1 - a),
      b: color.b * a + base.b * (1 - a),
    });
  };

  const readCssVar = (name, fallback) => {
    try {
      const value = getComputedStyle(root).getPropertyValue(name).trim();
      return value || fallback;
    } catch (_) {
      return fallback;
    }
  };

  const isDarkAppearance = () => {
    if (root.dataset.appearance === "dark") return true;
    if (root.dataset.appearance === "light") return false;
    const theme = root.getAttribute("data-theme") || "";
    if (/dark/i.test(theme)) return true;
    if (/light|grey|gray/i.test(theme)) return false;
    const bg = parseCssColor(readCssVar("--bg-primary", "#ffffff"));
    if (!bg) return false;
    return (0.2126 * bg.r + 0.7152 * bg.g + 0.0722 * bg.b) / 255 < 0.45;
  };

  const syncAppearance = () => {
    if (root.dataset.appearance === "dark" || root.dataset.appearance === "light") return;
    root.dataset.appearance = isDarkAppearance() ? "dark" : "light";
  };

  const resolveArticleFontSize = () => {
    const el =
      document.querySelector(".site-article .ProseMirror") ||
      document.querySelector(".site-article") ||
      document.body;
    try {
      const px = parseFloat(getComputedStyle(el).fontSize);
      if (Number.isFinite(px) && px > 0) return px;
    } catch (_) {}
    const fromVar = parseFloat(readCssVar("--editor-font-size", readCssVar("--inimark-editor-font-size", "16")));
    return Number.isFinite(fromVar) && fromVar > 0 ? fromVar : 16;
  };

  const resolveMermaidFontSize = () => Math.max(10, Math.round(resolveArticleFontSize()) - 2);

  const resolveDiagramContainerWidth = () => {
    const panel = document.querySelector(".site-article .diagram-panel");
    if (panel && panel.clientWidth > 0) return panel.clientWidth;
    const article = document.querySelector(".site-article");
    if (article && article.clientWidth > 0) return Math.max(280, article.clientWidth);
    return 640;
  };

  const buildMermaidThemeVariables = () => {
    const dark = isDarkAppearance();
    const fb = dark ? DARK_FALLBACKS : LIGHT_FALLBACKS;
    const contentBgRaw = readCssVar("--bg-primary", readCssVar("--inimark-content-bg", fb.contentBg));
    const contentBg = toMermaidColor(contentBgRaw, fb.contentBg, fb.contentBg);
    const solid = (raw, fallback) => toMermaidColor(raw, fallback, contentBg);
    const s = {
      surface: solid(readCssVar("--bg-surface", readCssVar("--inimark-surface", fb.surface)), fb.surface),
      secondary: solid(readCssVar("--bg-secondary", readCssVar("--inimark-bg", fb.secondary)), fb.secondary),
      tertiary: solid(
        readCssVar("--bg-tertiary", readCssVar("--inimark-surface-raised", fb.tertiary)),
        fb.tertiary,
      ),
      contentBg,
      code: solid(readCssVar("--bg-code", fb.code), fb.code),
      fg: solid(readCssVar("--text-primary", readCssVar("--inimark-fg", fb.fg)), fb.fg),
      muted: solid(readCssVar("--text-secondary", readCssVar("--inimark-muted-fg", fb.muted)), fb.muted),
      border: solid(readCssVar("--border", readCssVar("--inimark-border", fb.border)), fb.border),
      accent: solid(readCssVar("--accent", readCssVar("--inimark-accent", fb.accent)), fb.accent),
      accentHover: solid(readCssVar("--accent-hover", fb.accentHover), fb.accentHover),
      danger: solid(readCssVar("--danger", fb.danger), fb.danger),
      blockquoteBg: solid(readCssVar("--blockquote-bg", fb.blockquoteBg), fb.blockquoteBg),
      blockquoteBorder: solid(readCssVar("--blockquote-border", fb.blockquoteBorder), fb.blockquoteBorder),
    };
    const pieSectionText = dark ? s.contentBg : s.fg;
    const fontSize = resolveMermaidFontSize() + "px";
    return {
      darkMode: dark,
      background: "transparent",
      fontSize,
      primaryColor: s.surface,
      secondaryColor: s.secondary,
      tertiaryColor: s.tertiary,
      mainBkg: s.surface,
      secondBkg: s.secondary,
      primaryTextColor: s.fg,
      secondaryTextColor: s.fg,
      tertiaryTextColor: s.fg,
      textColor: s.fg,
      nodeTextColor: s.fg,
      primaryBorderColor: s.border,
      secondaryBorderColor: s.border,
      tertiaryBorderColor: s.border,
      lineColor: s.muted,
      arrowheadColor: s.muted,
      defaultLinkColor: s.muted,
      titleColor: s.accent,
      edgeLabelBackground: s.code,
      clusterBkg: s.secondary,
      clusterBorder: s.border,
      noteBkgColor: s.blockquoteBg,
      noteTextColor: s.fg,
      noteBorderColor: s.blockquoteBorder,
      actorBkg: s.surface,
      actorTextColor: s.fg,
      actorBorder: s.border,
      actorLineColor: s.border,
      labelBoxBkgColor: s.surface,
      labelBoxBorderColor: s.border,
      signalColor: s.muted,
      signalTextColor: s.fg,
      labelTextColor: s.fg,
      loopTextColor: s.fg,
      activationBorderColor: s.border,
      activationBkgColor: s.tertiary,
      sequenceNumberColor: s.contentBg,
      sectionBkgColor: s.surface,
      altSectionBkgColor: s.tertiary,
      sectionBkgColor2: s.surface,
      excludeBkgColor: s.danger,
      taskBorderColor: s.border,
      taskBkgColor: s.surface,
      taskTextColor: s.fg,
      taskTextOutsideColor: s.fg,
      taskTextLightColor: s.contentBg,
      taskTextDarkColor: s.fg,
      taskTextClickableColor: s.accent,
      activeTaskBorderColor: s.accent,
      activeTaskBkgColor: s.secondary,
      doneTaskBkgColor: s.code,
      doneTaskBorderColor: s.border,
      critBorderColor: s.danger,
      critBkgColor: s.secondary,
      gridColor: s.border,
      todayLineColor: s.danger,
      vertLineColor: s.border,
      personBkg: s.surface,
      personBorder: s.border,
      rowOdd: s.code,
      rowEven: s.secondary,
      transitionColor: s.muted,
      transitionLabelColor: s.fg,
      stateLabelColor: s.fg,
      stateBkg: s.surface,
      labelBackgroundColor: s.code,
      compositeBackground: s.secondary,
      altBackground: s.tertiary,
      compositeTitleBackground: s.tertiary,
      compositeBorder: s.border,
      innerEndBackground: s.fg,
      errorBkgColor: s.secondary,
      errorTextColor: s.danger,
      specialStateColor: s.accent,
      scaleLabelColor: s.fg,
      classText: s.fg,
      requirementBackground: s.surface,
      requirementBorderColor: s.border,
      requirementTextColor: s.fg,
      relationColor: s.muted,
      relationLabelBackground: s.code,
      relationLabelColor: s.fg,
      branchLabelColor: s.fg,
      tagLabelColor: s.fg,
      tagLabelBackground: s.code,
      tagLabelBorder: s.border,
      commitLabelColor: s.fg,
      commitLabelBackground: s.code,
      archEdgeColor: s.muted,
      archEdgeArrowColor: s.muted,
      archGroupBorderColor: s.border,
      quadrant1TextFill: s.fg,
      quadrant2TextFill: s.fg,
      quadrant3TextFill: s.fg,
      quadrant4TextFill: s.fg,
      quadrantPointTextFill: s.fg,
      quadrantXAxisTextFill: s.fg,
      quadrantYAxisTextFill: s.fg,
      quadrantTitleFill: s.accent,
      pieTitleTextColor: s.accent,
      pieSectionTextColor: pieSectionText,
      pieLegendTextColor: s.fg,
      pieStrokeColor: pieSectionText,
      vennTitleTextColor: s.accent,
      vennSetTextColor: s.fg,
      wardleyEvolutionColor: s.accent,
      xyChart: {
        titleColor: s.accent,
        dataLabelColor: s.fg,
        xAxisTitleColor: s.fg,
        xAxisLabelColor: s.fg,
        xAxisTickColor: s.muted,
        xAxisLineColor: s.muted,
        yAxisTitleColor: s.fg,
        yAxisLabelColor: s.fg,
        yAxisTickColor: s.muted,
        yAxisLineColor: s.muted,
        plotColorPalette: s.accent + "," + s.accentHover + "," + s.muted + "," + s.danger,
      },
      packet: {
        startByteColor: s.fg,
        endByteColor: s.fg,
        labelColor: s.fg,
        titleColor: s.accent,
        blockStrokeColor: s.border,
        blockFillColor: s.surface,
      },
      wardley: {
        axisTextColor: s.fg,
        componentLabelColor: s.fg,
        annotationTextColor: s.fg,
      },
    };
  };

  syncAppearance();

  const waitForMermaid = () =>
    new Promise((resolve, reject) => {
      if (window.mermaid) {
        resolve(window.mermaid);
        return;
      }
      let tries = 0;
      const timer = setInterval(() => {
        if (window.mermaid) {
          clearInterval(timer);
          resolve(window.mermaid);
        } else if (++tries > 200) {
          clearInterval(timer);
          reject(new Error("Mermaid failed to load"));
        }
      }, 25);
    });

  const markDiagramSuccess = (pre) => {
    const panel = pre.closest(".diagram-panel");
    const block = pre.closest(".code-block-node");
    if (panel) panel.dataset.diagramState = "success";
    if (block) {
      block.classList.add("diagram-success");
      block.classList.remove("diagram-pending");
    }
  };

  const readSvgIntrinsicSize = (svg) => {
    let w = 0;
    let h = 0;
    const vb = svg.getAttribute("viewBox");
    if (vb) {
      const parts = vb.trim().split(/[s,]+/).map(Number);
      if (parts.length === 4 && parts[2] > 0 && parts[3] > 0) {
        w = parts[2];
        h = parts[3];
      }
    }
    const style = svg.getAttribute("style") || "";
    const maxW = /max-width:s*([d.]+)px/i.exec(style);
    if (maxW) w = w || parseFloat(maxW[1]);
    const attrW = parseFloat(svg.getAttribute("width") || "");
    const attrH = parseFloat(svg.getAttribute("height") || "");
    if (Number.isFinite(attrW) && attrW > 0) w = w || attrW;
    if (Number.isFinite(attrH) && attrH > 0) h = h || attrH;
    if (!(w > 0) || !(h > 0)) {
      try {
        const bbox = svg.getBBox();
        if (bbox.width > 0 && bbox.height > 0) {
          w = w || bbox.width;
          h = h || bbox.height;
        }
      } catch (_) {}
    }
    return { w, h };
  };

  // Keep SVG at Mermaid's intrinsic size so themeVariables.fontSize (body−2px)
  // maps 1:1 to on-screen px. Only shrink when wider than the column.
  const fitMermaidSvg = (svg) => {
    let { w: intrinsicW, h: intrinsicH } = readSvgIntrinsicSize(svg);
    if (!(intrinsicW > 0)) return;
    if (!(intrinsicH > 0)) intrinsicH = intrinsicW;
    if (!svg.getAttribute("viewBox")) {
      svg.setAttribute("viewBox", "0 0 " + intrinsicW + " " + intrinsicH);
    }
    svg.removeAttribute("height");
    svg.setAttribute("width", String(intrinsicW));
    svg.style.width = intrinsicW + "px";
    svg.style.maxWidth = "100%";
    svg.style.height = "auto";
  };

  const fitMermaidDiagrams = (roots) => {
    roots.forEach((rootEl) => {
      const svgs = rootEl.tagName === "svg"
        ? [rootEl]
        : Array.from(rootEl.querySelectorAll("svg"));
      svgs.forEach((svg) => fitMermaidSvg(svg));
    });
  };

  const renderMermaidDiagrams = async () => {
    const nodes = Array.from(document.querySelectorAll("pre.mermaid"));
    if (!nodes.length) return;
    try {
      syncAppearance();
      const mermaid = await waitForMermaid();
      const fontPx = resolveMermaidFontSize();
      const containerW = resolveDiagramContainerWidth();
      const chartSize = Math.max(320, Math.min(containerW, 900));
      mermaid.initialize({
        startOnLoad: false,
        securityLevel: "strict",
        suppressErrorRendering: true,
        theme: "base",
        themeVariables: buildMermaidThemeVariables(),
        // useMaxWidth:false → absolute px size so fontSize stays 1:1 on screen
        flowchart: { useMaxWidth: false, htmlLabels: true },
        sequence: { useMaxWidth: false },
        gantt: { useMaxWidth: false },
        journey: { useMaxWidth: false },
        class: { useMaxWidth: false },
        state: { useMaxWidth: false },
        er: { useMaxWidth: false },
        pie: { useMaxWidth: false },
        quadrantChart: {
          useMaxWidth: false,
          chartWidth: chartSize,
          chartHeight: chartSize,
          pointLabelFontSize: fontPx,
          quadrantLabelFontSize: fontPx,
          xAxisLabelFontSize: fontPx,
          yAxisLabelFontSize: fontPx,
          titleFontSize: fontPx + 4,
        },
        xyChart: {
          useMaxWidth: false,
          width: chartSize,
          height: Math.round(chartSize * 0.62),
          titleFontSize: fontPx + 2,
        },
      });
      await mermaid.run({ nodes });
      nodes.forEach(markDiagramSuccess);
      fitMermaidDiagrams(nodes);
    } catch (error) {
      console.warn("Inimark site: Mermaid render failed", error);
    }
  };

  toggle?.addEventListener("click", () => {
    applyAppearance(currentMode() === "dark" ? "light" : "dark");
    // Mermaid SVG colors are baked at render time; reload to re-theme diagrams.
    if (document.querySelector("pre.mermaid, .diagram-panel svg")) {
      location.reload();
      return;
    }
  });

  const TREE_KEY = "inimark-site-tree";
  const loadTreeState = () => {
    try {
      const raw = localStorage.getItem(TREE_KEY);
      const parsed = raw ? JSON.parse(raw) : {};
      return parsed && typeof parsed === "object" ? parsed : {};
    } catch (_) {
      return {};
    }
  };
  const saveTreeState = (state) => {
    try {
      localStorage.setItem(TREE_KEY, JSON.stringify(state));
    } catch (_) {}
  };
  const setDirOpen = (li, open) => {
    const btn = li.querySelector(":scope > .site-tree-toggle");
    if (!btn) return;
    btn.setAttribute("aria-expanded", open ? "true" : "false");
    li.classList.toggle("is-collapsed", !open);
    btn.querySelector(".site-tree-chevron")?.classList.toggle("is-expanded", open);
    const nested = li.querySelector(":scope > .site-tree");
    if (nested) nested.hidden = !open;
  };
  document.querySelectorAll(".site-tree-toggle").forEach((btn) => {
    btn.addEventListener("click", () => {
      const li = btn.closest(".site-tree-dir");
      if (!li) return;
      const open = btn.getAttribute("aria-expanded") !== "false";
      setDirOpen(li, !open);
      const path = li.getAttribute("data-tree-path");
      if (!path) return;
      const state = loadTreeState();
      state[path] = !open;
      saveTreeState(state);
    });
  });

  const LANG_KEY = "inimark-site-lang";
  document.querySelectorAll(".site-lang-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      const lang = btn.getAttribute("data-lang");
      if (lang) localStorage.setItem(LANG_KEY, lang);
    });
  });

  const main = document.querySelector(".site-main");
  if (main) {
    const scrollRoot = document.scrollingElement || document.documentElement;
    const scrollToHash = (hash) => {
      if (!hash || hash === "#") return;
      const id = decodeURIComponent(hash.slice(1));
      const target = document.getElementById(id);
      if (!target) return;
      const top =
        target.getBoundingClientRect().top +
        scrollRoot.scrollTop -
        12;
      scrollRoot.scrollTo({ top, behavior: "smooth" });
    };
    main.addEventListener("click", (event) => {
      const link = event.target.closest('a[href^="#"]');
      if (!link) return;
      const href = link.getAttribute("href");
      if (!href || href === "#") return;
      event.preventDefault();
      scrollToHash(href);
      history.replaceState(null, "", href);
    });
    if (location.hash) scrollToHash(location.hash);
  }

  renderMermaidDiagrams();

  const GRAPH_SCALE_MIN = 0.12;
  const GRAPH_SCALE_MAX = 15;
  const ZOOM_LERP_K = 0.72;
  const PAN_DECAY_K = 0.78;
  const SETTINGS = {
    nodeSize: 50,
    linkThickness: 50,
    textOpacity: 50,
    animate: true,
    centerForce: 45,
    repulsion: 75,
    linkForce: 20,
    linkDistance: 70,
    showArrows: false,
  };

  function camLerp(current, target, k) {
    return current * k + target * (1 - k);
  }
  function graphSettingFactor(value) {
    return Math.max(0.05, value / 50);
  }
  function graphLabelAlpha(textOpacity, scale) {
    const fade = Math.max(0, Math.min(1, (textOpacity - 50) / 50));
    if (fade < 0.001) return 1;
    const span = GRAPH_SCALE_MAX - GRAPH_SCALE_MIN;
    const normalized = Math.max(0, Math.min(1, (scale - GRAPH_SCALE_MIN) / span));
    return Math.max(0.08, 1 - fade * (1 - normalized));
  }
  function cssVar(el, name, fallback) {
    const value = getComputedStyle(el).getPropertyValue(name).trim();
    return value || fallback;
  }
  function relativeHref(fromHtmlPath, toHtmlPath) {
    const fromParts = String(fromHtmlPath || "").replace(/\\/g, "/").split("/");
    fromParts.pop();
    const toParts = String(toHtmlPath || "").replace(/\\/g, "/").split("/");
    let i = 0;
    while (i < fromParts.length && i < toParts.length && fromParts[i] === toParts[i]) i++;
    const up = fromParts.length - i;
    const down = toParts.slice(i).join("/");
    return (up > 0 ? "../".repeat(up) : "") + down;
  }
  function parseGraphPayload(raw) {
    try { return JSON.parse(raw || "{}"); }
    catch { return null; }
  }

  /**
   * @param {HTMLElement} host
   * @param {object} payload
   * @param {{ lockCursor?: boolean }} [options]
   *   lockCursor: keep default arrow (preview rail). Modal keeps grab/pointer.
   */
  function mountSiteGraph(host, payload, options) {
    const canvas = host.querySelector(".site-graph-canvas");
    if (!(canvas instanceof HTMLCanvasElement)) return () => {};
    const lockCursor = !!(options && options.lockCursor);
    const nodesIn = Array.isArray(payload?.nodes) ? payload.nodes : [];
    if (!nodesIn.length) return () => {};

    const edgeIn = Array.isArray(payload.edges) ? payload.edges : [];
    const nodes = nodesIn.map((n) => ({
      id: n.id,
      label: n.label || n.id,
      href: n.href || "",
      center: !!n.center,
      degree: 0,
      x: 0, y: 0, vx: 0, vy: 0,
    }));
    const byId = () => new Map(nodes.map((n) => [n.id, n]));
    let edges = edgeIn
      .filter((e) => nodes.some((n) => n.id === e.source) && nodes.some((n) => n.id === e.target))
      .map((e) => ({ source: e.source, target: e.target }));

    function attachDegrees() {
      for (const n of nodes) n.degree = 0;
      const map = byId();
      for (const e of edges) {
        const a = map.get(e.source);
        const b = map.get(e.target);
        if (a) a.degree += 1;
        if (b) b.degree += 1;
      }
    }
    attachDegrees();

    let alpha = 1;
    let hoverId = null;
    let dragId = null;
    let panning = false;
    let scale = 1;
    let targetScale = 1;
    let panX = 0, panY = 0;
    let panvX = 0, panvY = 0;
    let panLastX = 0, panLastY = 0;
    let panVelDx = 0, panVelDy = 0, panVelDt = 16, panGestureT = 0;
    let zoomAnchorX = 0, zoomAnchorY = 0, zoomUseCursor = false;
    let downX = 0, downY = 0, pointerMoved = false;
    let adjacency = new Map();
    let dirty = true;
    let width = 240, height = 200;
    let disposed = false;
    let raf = 0;

    function setCursor(value) {
      if (lockCursor) {
        canvas.style.cursor = "default";
        return;
      }
      canvas.style.cursor = value;
    }
    setCursor("default");

    function rebuildAdjacency() {
      adjacency = new Map(nodes.map((n) => [n.id, new Set()]));
      for (const e of edges) {
        adjacency.get(e.source)?.add(e.target);
        adjacency.get(e.target)?.add(e.source);
      }
    }

    function seedLayout() {
      const n = Math.max(nodes.length, 1);
      const radius = Math.max(120, 42 * Math.sqrt(n));
      nodes.forEach((node, i) => {
        if (node.center) { node.x = 0; node.y = 0; }
        else {
          const angle = i * 2.399963;
          const r = radius * Math.sqrt((i + 1) / n);
          node.x = Math.cos(angle) * r;
          node.y = Math.sin(angle) * r;
        }
        node.vx = 0; node.vy = 0;
      });
      alpha = 1;
    }

    function setScaleImmediate(next) {
      scale = targetScale = Math.max(GRAPH_SCALE_MIN, Math.min(GRAPH_SCALE_MAX, next));
    }

    function fitCamera(pad) {
      if (!nodes.length || width <= 0 || height <= 0) {
        setScaleImmediate(1);
        panX = width / 2; panY = height / 2;
        panvX = panvY = 0;
        return;
      }
      let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
      for (const node of nodes) {
        minX = Math.min(minX, node.x); maxX = Math.max(maxX, node.x);
        minY = Math.min(minY, node.y); maxY = Math.max(maxY, node.y);
      }
      const margin = 18;
      const bw = Math.max(maxX - minX, 1) + margin * 2;
      const bh = Math.max(maxY - minY, 1) + margin * 2;
      const sx = (width - pad * 2) / bw;
      const sy = (height - pad * 2) / bh;
      setScaleImmediate(Math.min(sx, sy));
      const cx = (minX + maxX) / 2;
      const cy = (minY + maxY) / 2;
      panX = width / 2 - cx * scale;
      panY = height / 2 - cy * scale;
      panvX = panvY = 0;
    }

    function worldToScreen(wx, wy) {
      return { x: wx * scale + panX, y: wy * scale + panY };
    }
    function screenToWorld(sx, sy) {
      return { x: (sx - panX) / scale, y: (sy - panY) / scale };
    }

    function stepForces(settling) {
      if (!nodes.length) return;
      const alphaTarget = settling ? 0 : SETTINGS.animate ? 0.08 : 0;
      if (!settling && !SETTINGS.animate && alpha < 0.001) return;

      const n = nodes.length;
      const map = byId();
      const centerStrength = (SETTINGS.centerForce / 100) * 0.55;
      const charge = -(60 + SETTINGS.repulsion * 7);
      const linkStrength = (SETTINGS.linkForce / 100) * 0.65;
      const linkDistance = 70 + SETTINGS.linkDistance * 3.4;
      const nodeSizeFactor = graphSettingFactor(SETTINGS.nodeSize);
      const collideBase = 14 * nodeSizeFactor;
      const distanceMax2 = 520 * 520;

      for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
          const a = nodes[i], b = nodes[j];
          let dx = b.x - a.x, dy = b.y - a.y;
          let distSq = dx * dx + dy * dy;
          if (distSq >= distanceMax2) continue;
          if (distSq < 0.01) {
            dx = (Math.random() - 0.5) * 0.5;
            dy = (Math.random() - 0.5) * 0.5;
            distSq = dx * dx + dy * dy;
          }
          const w = (charge * alpha) / distSq;
          dx *= w; dy *= w;
          a.vx += dx; a.vy += dy;
          b.vx -= dx; b.vy -= dy;
        }
      }

      if (linkStrength > 0.001) {
        for (const edge of edges) {
          const a = map.get(edge.source), b = map.get(edge.target);
          if (!a || !b) continue;
          let dx = b.x - a.x, dy = b.y - a.y;
          const dist = Math.hypot(dx, dy) || 1e-6;
          const degreeSum = Math.max(1, a.degree + b.degree);
          const bias = a.degree / degreeSum;
          const strength = linkStrength * alpha;
          const k = ((dist - linkDistance) / dist) * strength;
          dx *= k; dy *= k;
          a.vx += dx * (1 - bias); a.vy += dy * (1 - bias);
          b.vx -= dx * bias; b.vy -= dy * bias;
        }
      }

      const maxDeg = Math.max(1, ...nodes.map((node) => node.degree));
      for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
          const a = nodes[i], b = nodes[j];
          let dx = b.x - a.x, dy = b.y - a.y;
          let dist = Math.hypot(dx, dy);
          const ra = collideBase * (0.7 + (a.degree / maxDeg) * 0.6);
          const rb = collideBase * (0.7 + (b.degree / maxDeg) * 0.6);
          const minDist = ra + rb;
          if (dist >= minDist) continue;
          if (dist < 1e-6) {
            dx = (Math.random() - 0.5) * 0.2;
            dy = (Math.random() - 0.5) * 0.2;
            dist = Math.hypot(dx, dy) || 1e-6;
          }
          const push = ((minDist - dist) / dist) * 0.5 * alpha;
          dx *= push; dy *= push;
          a.vx -= dx; a.vy -= dy;
          b.vx += dx; b.vy += dy;
        }
      }

      for (const node of nodes) {
        if (dragId === node.id) { node.vx = 0; node.vy = 0; continue; }
        node.vx += -node.x * centerStrength * alpha;
        node.vy += -node.y * centerStrength * alpha;
        node.vx *= 0.6; node.vy *= 0.6;
        node.x += node.vx; node.y += node.vy;
      }
      alpha += (alphaTarget - alpha) * (settling ? 0.05 : 0.0228);
    }

    function nodeScaleClamp() {
      return Math.min(3.2, Math.max(0.65, scale));
    }
    function nodeRadius(node, maxDeg, scaleClamp, nodeScale) {
      const degreeBoost = 5 + (node.degree / maxDeg) * 9;
      return degreeBoost * scaleClamp * nodeScale;
    }
    function labelFontSize(drawR) {
      const t = Math.max(0, Math.min(1, (drawR - 4) / 32));
      return 9 + t * 16;
    }
    function hoverFocus() {
      if (!hoverId) return null;
      const focus = new Set([hoverId]);
      const neighbors = adjacency.get(hoverId);
      if (neighbors) for (const id of neighbors) focus.add(id);
      return focus;
    }

    function draw() {
      const dpr = Math.max(1, Math.min(window.devicePixelRatio || 1, 2));
      const rect = host.getBoundingClientRect();
      width = Math.max(1, Math.floor(rect.width));
      height = Math.max(1, Math.floor(rect.height));
      const bw = Math.floor(width * dpr), bh = Math.floor(height * dpr);
      if (canvas.width !== bw || canvas.height !== bh) {
        canvas.width = bw; canvas.height = bh;
        canvas.style.width = width + "px";
        canvas.style.height = height + "px";
      }
      const ctx = canvas.getContext("2d");
      if (!ctx) return;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, width, height);

      const nodeColor = cssVar(host, "--inimark-graph-node", "#b4b4b4");
      const nodeActive = cssVar(host, "--inimark-graph-node-active", "#d0d0d0");
      const labelColor = cssVar(host, "--inimark-graph-label", "#dcdcdc");
      const linkColor = cssVar(host, "--inimark-graph-link", "#3c3c3c");
      const accent = cssVar(host, "--inimark-graph-highlight", cssVar(host, "--accent", "#64748b"));
      const uiFont = cssVar(document.documentElement, "--font-ui", "system-ui, sans-serif");
      const nodeScale = graphSettingFactor(SETTINGS.nodeSize);
      const linkScale = graphSettingFactor(SETTINGS.linkThickness);
      const textAlpha = graphLabelAlpha(SETTINGS.textOpacity, scale);
      const focus = hoverFocus();
      const dimming = focus != null;
      const map = byId();
      const baseLine = Math.max(0.75, 1.25 * linkScale);

      const drawEdge = (edge, color, a, widthMul) => {
        const na = map.get(edge.source), nb = map.get(edge.target);
        if (!na || !nb) return;
        const sa = worldToScreen(na.x, na.y);
        const sb = worldToScreen(nb.x, nb.y);
        ctx.strokeStyle = color;
        ctx.globalAlpha = a;
        ctx.lineWidth = baseLine * widthMul;
        ctx.beginPath();
        ctx.moveTo(sa.x, sa.y);
        ctx.lineTo(sb.x, sb.y);
        ctx.stroke();
      };

      for (const edge of edges) {
        const hot = focus && hoverId &&
          ((edge.source === hoverId && focus.has(edge.target)) ||
           (edge.target === hoverId && focus.has(edge.source)));
        if (hot) continue;
        drawEdge(edge, linkColor, dimming ? 0.18 : 0.85, 1);
      }
      if (focus && hoverId) {
        for (const edge of edges) {
          const hot =
            (edge.source === hoverId && focus.has(edge.target)) ||
            (edge.target === hoverId && focus.has(edge.source));
          if (!hot) continue;
          drawEdge(edge, accent, 1, 1.85);
        }
      }
      ctx.globalAlpha = 1;

      const maxDeg = Math.max(1, ...nodes.map((n) => n.degree));
      const scaleClamp = nodeScaleClamp();

      const drawNode = (node, highlighted) => {
        const s = worldToScreen(node.x, node.y);
        if (s.x < -40 || s.y < -40 || s.x > width + 40 || s.y > height + 40) return;
        const r = nodeRadius(node, maxDeg, scaleClamp, nodeScale);
        const isHover = node.id === hoverId;
        const drawR = r * (isHover ? 1.15 : 1);
        const fontSize = labelFontSize(drawR);
        ctx.beginPath();
        if (highlighted) {
          ctx.fillStyle = isHover ? accent : nodeActive;
          ctx.globalAlpha = 1;
        } else if (dimming) {
          ctx.fillStyle = node.center ? nodeActive : nodeColor;
          ctx.globalAlpha = 0.22;
        } else {
          ctx.fillStyle = node.center ? nodeActive : nodeColor;
          ctx.globalAlpha = 1;
        }
        ctx.arc(s.x, s.y, drawR, 0, Math.PI * 2);
        ctx.fill();

        const labelA = highlighted ? Math.max(textAlpha, 0.92) : dimming ? textAlpha * 0.25 : textAlpha;
        if (labelA > 0.02) {
          ctx.globalAlpha = labelA;
          ctx.fillStyle = highlighted ? (isHover ? accent : labelColor) : labelColor;
          ctx.font = (isHover ? "600 " : "") + fontSize + "px " + uiFont;
          ctx.textAlign = "center";
          ctx.textBaseline = "alphabetic";
          ctx.fillText(node.label.slice(0, 24), s.x, s.y + drawR + fontSize + 2);
        }
        ctx.globalAlpha = 1;
      };

      for (const node of nodes) {
        if (focus?.has(node.id)) continue;
        drawNode(node, false);
      }
      if (focus) {
        for (const node of nodes) {
          if (!focus.has(node.id) || node.id === hoverId) continue;
          drawNode(node, true);
        }
        const hovered = hoverId ? map.get(hoverId) : null;
        if (hovered) drawNode(hovered, true);
      }
    }

    function updateZoom() {
      targetScale = Math.max(GRAPH_SCALE_MIN, Math.min(GRAPH_SCALE_MAX, targetScale));
      const cur = scale, next = targetScale;
      const gap = (cur > next ? cur / next : next / cur) - 1;
      if (gap < 0.008) {
        if (gap > 0) { scale = next; return true; }
        return false;
      }
      const zx = zoomUseCursor ? zoomAnchorX : width / 2;
      const zy = zoomUseCursor ? zoomAnchorY : height / 2;
      const wx = (zx - panX) / cur, wy = (zy - panY) / cur;
      scale = camLerp(cur, next, ZOOM_LERP_K);
      panX = zx - wx * scale;
      panY = zy - wy * scale;
      return true;
    }

    function applyPanInertia() {
      if (panning) return false;
      if (Math.abs(panvX) < 1e-4 && Math.abs(panvY) < 1e-4) {
        panvX = panvY = 0; return false;
      }
      panX += (1000 / 60) * panvX;
      panY += (1000 / 60) * panvY;
      panvX = camLerp(panvX, 0, PAN_DECAY_K);
      panvY = camLerp(panvY, 0, PAN_DECAY_K);
      return true;
    }

    function hitNode(clientX, clientY) {
      const rect = canvas.getBoundingClientRect();
      const world = screenToWorld(clientX - rect.left, clientY - rect.top);
      const maxDeg = Math.max(1, ...nodes.map((n) => n.degree));
      const scaleClamp = nodeScaleClamp();
      const nodeScale = graphSettingFactor(SETTINGS.nodeSize);
      let best = null, bestDist = Infinity;
      for (const node of nodes) {
        const rScreen = nodeRadius(node, maxDeg, scaleClamp, nodeScale);
        const hitR = Math.max(rScreen / Math.max(scale, 0.001), 8 / Math.max(scale, 0.3));
        const d = Math.hypot(node.x - world.x, node.y - world.y);
        const score = d - (node.center ? 0.5 : 0);
        if (d <= hitR && score < bestDist) { bestDist = score; best = node; }
      }
      return best;
    }

    function tick() {
      if (disposed) return;
      const rect = host.getBoundingClientRect();
      width = Math.max(1, Math.floor(rect.width));
      height = Math.max(1, Math.floor(rect.height));
      let simulating = false;
      if (nodes.length) {
        const before = alpha;
        stepForces(false);
        simulating = alpha >= 0.001 || before >= 0.001;
      }
      const zooming = updateZoom();
      const coasting = applyPanInertia();
      if (dirty || simulating || zooming || coasting || dragId) {
        draw();
        dirty = false;
      }
      raf = requestAnimationFrame(tick);
    }

    const onPointerDown = (event) => {
      const hit = hitNode(event.clientX, event.clientY);
      downX = event.clientX; downY = event.clientY; pointerMoved = false;
      if (hit && event.button === 0) {
        dragId = hit.id;
        hoverId = hit.id;
        panning = false;
        setCursor(lockCursor ? "default" : "pointer");
        canvas.setPointerCapture(event.pointerId);
        dirty = true;
        return;
      }
      if (event.button === 0 || event.button === 1) {
        panning = true;
        dragId = null;
        hoverId = null;
        panLastX = event.clientX; panLastY = event.clientY;
        panvX = panvY = 0;
        panVelDx = panVelDy = 0; panVelDt = 16;
        panGestureT = performance.now();
        canvas.setPointerCapture(event.pointerId);
        setCursor(lockCursor ? "default" : "grabbing");
        dirty = true;
      }
    };

    const onPointerMove = (event) => {
      if (Math.hypot(event.clientX - downX, event.clientY - downY) > 4) pointerMoved = true;
      if (panning) {
        const dx = event.clientX - panLastX;
        const dy = event.clientY - panLastY;
        const now = performance.now();
        const dt = Math.max(1, now - panGestureT);
        panX += dx; panY += dy;
        panVelDx = camLerp(panVelDx, dx, 0.8);
        panVelDy = camLerp(panVelDy, dy, 0.8);
        panVelDt = camLerp(panVelDt, dt, 0.8);
        panGestureT = now;
        panLastX = event.clientX; panLastY = event.clientY;
        dirty = true;
        return;
      }
      if (dragId) {
        const node = nodes.find((n) => n.id === dragId);
        if (!node) return;
        const rect = canvas.getBoundingClientRect();
        const world = screenToWorld(event.clientX - rect.left, event.clientY - rect.top);
        node.x = world.x; node.y = world.y;
        node.vx = 0; node.vy = 0;
        alpha = Math.max(alpha, 0.12);
        setCursor(lockCursor ? "default" : "pointer");
        dirty = true;
        return;
      }
      const hit = hitNode(event.clientX, event.clientY);
      const next = hit?.id ?? null;
      if (next !== hoverId) { hoverId = next; dirty = true; }
      setCursor(lockCursor ? "default" : (hit ? "pointer" : "grab"));
    };

    const endPointer = (event) => {
      if (panning) {
        panning = false;
        const releasedAgo = performance.now() - panGestureT;
        if (releasedAgo < 64 && panVelDt > 0) {
          panvX = panVelDx / panVelDt;
          panvY = panVelDy / panVelDt;
        }
        setCursor(lockCursor ? "default" : "grab");
      }
      if (dragId) {
        const id = dragId;
        dragId = null;
        if (!pointerMoved) {
          const node = nodes.find((n) => n.id === id);
          if (node && node.href) location.href = node.href;
        }
        alpha = Math.max(alpha, SETTINGS.animate ? 0.2 : 0.12);
        setCursor(lockCursor ? "default" : "grab");
      }
      try { canvas.releasePointerCapture(event.pointerId); } catch {}
      dirty = true;
    };

    const onWheel = (event) => {
      event.preventDefault();
      const rect = canvas.getBoundingClientRect();
      zoomUseCursor = true;
      zoomAnchorX = event.clientX - rect.left;
      zoomAnchorY = event.clientY - rect.top;
      const factor = event.deltaY < 0 ? 1.12 : 1 / 1.12;
      targetScale = Math.max(GRAPH_SCALE_MIN, Math.min(GRAPH_SCALE_MAX, targetScale * factor));
      dirty = true;
    };

    canvas.addEventListener("pointerdown", onPointerDown);
    canvas.addEventListener("pointermove", onPointerMove);
    canvas.addEventListener("pointerup", endPointer);
    canvas.addEventListener("pointercancel", endPointer);
    canvas.addEventListener("wheel", onWheel, { passive: false });

    rebuildAdjacency();
    seedLayout();
    for (let i = 0; i < 160; i++) stepForces(true);
    const rect = host.getBoundingClientRect();
    width = Math.max(rect.width, 200);
    height = Math.max(rect.height, 160);
    fitCamera(28);
    if (SETTINGS.animate) alpha = Math.max(alpha, 0.2);
    dirty = true;
    raf = requestAnimationFrame(tick);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      canvas.removeEventListener("pointerdown", onPointerDown);
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerup", endPointer);
      canvas.removeEventListener("pointercancel", endPointer);
      canvas.removeEventListener("wheel", onWheel);
    };
  }

  let activeModalDispose = null;
  let globalGraphCache = null;

  function closeGraphModal() {
    if (activeModalDispose) {
      activeModalDispose();
      activeModalDispose = null;
    }
    document.querySelector(".site-graph-modal")?.remove();
    document.documentElement.classList.remove("site-graph-modal-open");
  }

  function openGraphModal(title, payload) {
    closeGraphModal();
    const overlay = document.createElement("div");
    overlay.className = "site-graph-modal";
    overlay.innerHTML =
      '<div class="site-graph-modal-dialog" role="dialog" aria-modal="true">' +
      '<div class="site-graph-modal-head">' +
      '<div class="site-graph-modal-title"></div>' +
      '<button type="button" class="site-graph-modal-close" aria-label="Close">×</button>' +
      "</div>" +
      '<div class="site-graph-modal-body"><div class="site-graph-modal-host">' +
      '<canvas class="site-graph-canvas" aria-label="Relationship graph"></canvas>' +
      "</div></div></div>";
    overlay.querySelector(".site-graph-modal-title").textContent = title;
    document.body.appendChild(overlay);
    document.documentElement.classList.add("site-graph-modal-open");

    const host = overlay.querySelector(".site-graph-modal-host");
    activeModalDispose = mountSiteGraph(host, payload, { lockCursor: false });

    const onKey = (event) => {
      if (event.key === "Escape") closeGraphModal();
    };
    const onBackdrop = (event) => {
      if (event.target === overlay) closeGraphModal();
    };
    overlay.querySelector(".site-graph-modal-close")?.addEventListener("click", closeGraphModal);
    overlay.addEventListener("click", onBackdrop);
    window.addEventListener("keydown", onKey);
    const prevDispose = activeModalDispose;
    activeModalDispose = () => {
      window.removeEventListener("keydown", onKey);
      prevDispose?.();
    };
  }

  function readEmbeddedGlobalGraph() {
    if (typeof window !== "undefined" && window.__INIMARK_GLOBAL_GRAPH__) {
      return window.__INIMARK_GLOBAL_GRAPH__;
    }
    return null;
  }

  async function loadGlobalGraph(url, centerId, pageHtmlPath) {
    if (!globalGraphCache) {
      const embedded = readEmbeddedGlobalGraph();
      if (embedded && Array.isArray(embedded.nodes)) {
        globalGraphCache = embedded;
      } else if (url) {
        const res = await fetch(url);
        if (!res.ok) throw new Error("Failed to load global graph (" + res.status + ")");
        globalGraphCache = await res.json();
      } else {
        throw new Error("Global graph data is missing");
      }
    }
    const raw = globalGraphCache;
    const nodes = (Array.isArray(raw.nodes) ? raw.nodes : []).map((n) => ({
      id: n.id,
      label: n.label || n.id,
      href: n.htmlPath ? relativeHref(pageHtmlPath, n.htmlPath) : (n.href || ""),
      center: n.id === centerId,
    }));
    const edges = Array.isArray(raw.edges) ? raw.edges : [];
    return { centerId, nodes, edges };
  }

  function findPreviewHost(fromEl) {
    const section = fromEl.closest(".site-graph");
    return section?.querySelector(".site-graph-host[data-graph-preview]") || null;
  }

  document.querySelectorAll(".site-graph-host[data-graph-preview]").forEach((host) => {
    const dataEl = host.querySelector(".site-graph-data");
    const localPayload = parseGraphPayload(dataEl?.textContent);
    if (localPayload) mountSiteGraph(host, localPayload, { lockCursor: true });
  });

  document.addEventListener("click", async (event) => {
    const btn = event.target.closest?.("[data-graph-mode]");
    if (!btn) return;
    event.preventDefault();
    event.stopPropagation();

    const host = findPreviewHost(btn);
    const dataEl = host?.querySelector(".site-graph-data");
    const localPayload = parseGraphPayload(dataEl?.textContent);
    const pageHtml = host?.getAttribute("data-page-html") || "";
    const globalUrl = host?.getAttribute("data-global-graph") || "";
    const mode = btn.getAttribute("data-graph-mode");

    try {
      if (mode === "local") {
        openGraphModal("Local graph", localPayload || { nodes: [], edges: [] });
        return;
      }
      if (mode === "global") {
        const centerId = localPayload?.centerId || "";
        const payload = await loadGlobalGraph(globalUrl, centerId, pageHtml);
        if (!payload.nodes.length) throw new Error("Global graph has no nodes");
        openGraphModal("Global graph", payload);
      }
    } catch (err) {
      console.error(err);
      const message = err && err.message ? err.message : String(err);
      window.alert("Failed to open global graph:\n" + message);
    }
  });

})();
